const textTitles={"commerce": "商品文案与客服", "marketing": "广告创意与营销文案", "development": "代码与研发文档", "knowledge": "知识问答与流程说明", "education": "教案与题目讲解", "real-estate": "房源说明与看房沟通", "retail": "门店运营文案", "restaurant": "菜单说明与顾客沟通", "travel": "行程设计与出行说明", "hospitality": "住客服务与入住指引", "manufacturing": "工艺文档与质量记录", "logistics": "物流异常与操作说明", "finance-ops": "财务制度与对账说明", "legal-ops": "合同摘要与审阅辅助", "health-ops": "行政说明与导诊文案", "recruitment": "岗位文案与入职材料", "gaming": "世界观与分支对白", "publishing": "稿件编辑与内容摘要", "consulting": "研究分析与提案撰写", "architecture": "设计说明与方案提案", "agriculture": "农事记录与产品介绍", "nonprofit": "项目说明与资助材料", "local-services": "服务说明与售后答复", "events": "议程文案与活动策划"};
export function dimensionBrief(industry,dimension){
 if(dimension==='text')return {title:textTitles[industry.id],inputs:industry.inputs,output:industry.deliverable,method:industry.steps.map(step=>step[0]).join(' → '),acceptance:industry.acceptance};
 return workflowBriefs[industry.id]?.[dimension];
}
export function dimensionPlans(industry,dimension){
 if(dimension==='text')return industry.plans;
 const b=dimensionBrief(industry,dimension);
 if(!b)return [];
 let recipes,approaches;
 if(dimension==='image'){
  recipes=b.family==='edit'?[['image-pro'],['kolors'],['image-flash']]:[['image-pro'],['kolors'],['flux']];
  approaches=[
   '用参考素材确认主体与构图，先出样张，再统一延展尺寸；复杂细节逐张修订。',
   '免费图只做背景或概念草稿；主体沿用授权实拍，准确文字用排版工具添加。',
   b.family==='edit'?'先锁定一版参考图，仅修改需要变更的区域，复用已通过审核的主体。':'用快速文生图探索多个构图，仅对选中的草图做人工细化与排版。'
  ];
 }else if(dimension==='video'){
  recipes=b.family==='kling'?[['kling'],['veo-lite'],['veo-fast']]:[['veo'],['veo-lite'],['veo-fast']];
  approaches=[
   b.family==='kling'?'准备已确认首尾帧，逐镜生成并检查动作与主体一致性；失真片段重做。':'先逐镜确认分镜与声音，再生成短镜头并剪辑，逐帧处理明显失真。',
   '全片以现有素材和静帧剪辑为主，只为最关键的一个镜头购买生成；不承诺免费成片。',
   '先用静态分镜确定节奏，关键镜头生成一次后复用，转场与字幕交给剪辑工具。'
  ];
 }else if(dimension==='audio'){
  recipes=[['tts-pro'],['cosy'],['tts']];
  approaches=[
   '先试听角色、语速和情绪样稿，再逐段合成；专名、数字与多角色衔接人工精修。',
   '仅在已有自部署资源时使用开源模型；先做一种声音的短样，不合适则回到人工录音或另行试算托管 API。',
   '常用提示与固定片段缓存，只重生成更新部分；用词表校音并批量抽听。'
  ];
 }else{
  recipes=specialtyRecipes[b.family];approaches=specialtyApproaches[b.family];
 }
 return ids.map((id,n)=>({id,label:labels[n],models:recipes[n],approach:approaches[n],
  actions:[{label:'准备行业输入',text:b.inputs},{label:'执行核心流程',text:b.method},{label:'按本档控制投入',text:approaches[n]},{label:'交付与验收',text:b.output+'。'+b.acceptance}],
  tradeoff:n===0?'增加复核与迭代投入，优先保证此交付物可用；这是选型建议，尚无本站行业效果实测。':n===1?'优先降低本方案新增支出，会缩小自动化范围；免费配额、自部署算力和人工时间不能混算为零。':'通过复用、批处理与异常复核控制投入；需用真实样本确认稳定性，失败任务保留人工接管。'
 }));
}
